            throw new InvalidOwnerPostcodeException(postcode);
        }
        int[] range = REGION_RANGE.get(Locality.of(request.getCity()));
        if (range != null) {
            int value = Integer.parseInt(trimmed);
            if (value < range[0] || value > range[1]) {
                throw new InvalidOwnerPostcodeException(postcode);
            }
        }
        request.setPostcode(trimmed);
    }
}

